void dfs(int v, int p) {
    parent[v] = p;
    tin[v] = timer;
    euler[timer++] = v;
    for (int to : g[v]) if (to != p) {
        depth[to] = depth[v] + 1;
        dfs(to, v);
    }
    tout[v] = timer;
    euler[timer++] = v;
