def cartesian_tree(a: list[int]):
    n = len(a)
    left, right, parent = [-1] * n, [-1] * n, [-1] * n
    st: list[int] = []
    for i, v in enumerate(a):
        last = -1
        while st and a[st[-1]] > v:
            last = st.pop()
        if st:
            right[st[-1]] = i
            parent[i] = st[-1]
        if last != -1:
            left[i] = last
            parent[last] = i
        st.append(i)
    root = st[0] if st else -1
    while root != -1 and parent[root] != -1:
        root = parent[root]
    return root, left, right, parent

