namespace treap {
using ll = long long;
mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

struct Node {
    int prio, sz;
    ll val, sum;
    bool rev;
    Node *l, *r;
    Node(ll v) : prio(rng()), sz(1), val(v), sum(v), rev(false), l(nullptr), r(nullptr) {}
};

int size(Node* t) { return t ? t->sz : 0; }
ll get_sum(Node* t) { return t ? t->sum : 0; }

void pull(Node* t) {
    if (!t) return;
    t->sz = 1 + size(t->l) + size(t->r);
    t->sum = t->val + get_sum(t->l) + get_sum(t->r);
}
void push(Node* t) {
    if (!t || !t->rev) return;
    swap(t->l, t->r);
    if (t->l) t->l->rev ^= 1;
    if (t->r) t->r->rev ^= 1;
    t->rev = false;
}

void split(Node* t, int k, Node*& a, Node*& b) { // first k elements -> a
    if (!t) { a = b = nullptr; return; }
    push(t);
    if (size(t->l) >= k) {
        split(t->l, k, a, t->l);
        b = t;
        pull(b);
    } else {
        split(t->r, k - size(t->l) - 1, t->r, b);
        a = t;
        pull(a);
    }
}

Node* merge(Node* a, Node* b) {
    if (!a || !b) return a ? a : b;
    push(a); push(b);
    if (a->prio < b->prio) {
        a->r = merge(a->r, b);
        pull(a);
        return a;
    }
    b->l = merge(a, b->l);
    pull(b);
    return b;
}

void reverse_seg(Node*& root, int ql, int qr) { // 0-indexed inclusive
    Node *a, *b, *c;
    split(root, ql, a, b);
    split(b, qr - ql + 1, b, c);
    if (b) b->rev ^= 1;
    root = merge(a, merge(b, c));
}
} // namespace treap

namespace splay_concepts {
// Minimal rotate + splay sketch (explicit parent pointers). Niche — prefer treap for sequences.
struct Node {
    Node *l, *r, *p;
    int sz;
    Node() : l(nullptr), r(nullptr), p(nullptr), sz(1) {}
};

void pull(Node* x) {
    x->sz = 1 + (x->l ? x->l->sz : 0) + (x->r ? x->r->sz : 0);
}
void rotate(Node* x) {
    Node* p = x->p;
    Node* g = p->p;
    if (p->l == x) {
        p->l = x->r;
        if (x->r) x->r->p = p;
        x->r = p;
    } else {
        p->r = x->l;
        if (x->l) x->l->p = p;
        x->l = p;
    }
    p->p = x;
    x->p = g;
    if (g) {
        if (g->l == p) g->l = x;
        else if (g->r == p) g->r = x;
    }
    pull(p);
    pull(x);
}
void splay(Node* x) {
    while (x->p) {
        Node* p = x->p;
        Node* g = p->p;
        if (!g) rotate(x);
        else if ((g->l == p) == (p->l == x)) { // zig-zig
            rotate(p);
            rotate(x);
        } else { // zig-zag
            rotate(x);
            rotate(x);
        }
    }
}
} // namespace splay_concepts

namespace rbst {
// Insert-at-root randomized BST (theoretical twin of treap). Prefer treap:: in contests.
struct Node {
    int key, sz;
    Node *l, *r;
    Node(int k) : key(k), sz(1), l(nullptr), r(nullptr) {}
};
int size(Node* t) { return t ? t->sz : 0; }
void pull(Node* t) { if (t) t->sz = 1 + size(t->l) + size(t->r); }

Node* rotate_right(Node* p) {
    Node* x = p->l;
    p->l = x->r;
    x->r = p;
    pull(p);
    pull(x);
    return x;
}
Node* rotate_left(Node* p) {
    Node* x = p->r;
    p->r = x->l;
    x->l = p;
    pull(p);
    pull(x);
    return x;
}

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

Node* insert(Node* t, int key) {
    if (!t) return new Node(key);
    // probability 1/(sz+1) to become new root
    if (uniform_int_distribution<int>(0, size(t))(rng) == 0) {
        // insert at root: standard BST insert then rotate up (simplified path)
        if (key < t->key) {
            t->l = insert(t->l, key);
            t = rotate_right(t);
        } else {
            t->r = insert(t->r, key);
            t = rotate_left(t);
        }
        return t;
    }
    if (key < t->key) t->l = insert(t->l, key);
    else t->r = insert(t->r, key);
    pull(t);
    return t;
}
} // namespace rbst

