// C++17 — iterative binary lifting (1-indexed nodes, root = 1, parent[root]=0)
namespace binlift {
constexpr int N = 200005, LOG = 18; // 2^18 > 2e5
int n, up[LOG][N], dep[N];
vector<int> g[N];

void build(int root = 1) {
    // parent + depth via BFS (iterative)
    fill(up[0], up[0] + n + 1, 0);
    fill(dep, dep + n + 1, 0);
    queue<int> q;
    q.push(root);
    dep[root] = 0;
    up[0][root] = 0;
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int to : g[v]) if (to != up[0][v]) {
            up[0][to] = v;
            dep[to] = dep[v] + 1;
            q.push(to);
        }
    }
    for (int j = 1; j < LOG; ++j)
        for (int v = 1; v <= n; ++v)
            up[j][v] = up[j - 1][up[j - 1][v]];
}

int kth(int v, int k) {
    if (k > dep[v]) return 0;
    for (int j = 0; j < LOG; ++j)
        if (k & (1 << j)) v = up[j][v];
    return v;
}

int dist(int u, int v, int lca) {
    return dep[u] + dep[v] - 2 * dep[lca];
}
} // namespace binlift

