# Python 3.11+ — Fenwick subtree ops
class Fenwick:
    def __init__(self, n: int):
        self.n = n
        self.b = [0] * (n + 1)
    def add(self, i: int, x: int) -> None:
        while i <= self.n:
            self.b[i] += x
            i += i & -i
    def sum(self, i: int) -> int:
        r = 0
        while i > 0:
            r += self.b[i]
            i -= i & -i
        return r
    def range(self, l: int, r: int) -> int:
        return self.sum(r) - self.sum(l - 1)

