void add_color(int c) {
    if (freq[c] == 0) ++distinct;
    ++freq[c];
}
void rem_color(int c) {
    --freq[c];
    if (freq[c] == 0) --distinct;
}

int dfs_sz(int v, int p) {
    sz[v] = 1; heavy[v] = -1;
    int best = 0;
    for (int to : g[v]) if (to != p) {
        int s = dfs_sz(to, v);
        sz[v] += s;
        if (s > best) best = s, heavy[v] = to;
    }
    return sz[v];
}

void dfs_time(int v, int p) {
    tin[v] = ++timer;
    ver[timer] = v;
    for (int to : g[v]) if (to != p) dfs_time(to, v);
