def kosaraju(n: int, g: list[list[int]]) -> tuple[list[int], int]:
    gr = [[] for _ in range(n)]
    for v, outs in enumerate(g):
        for to in outs:
            gr[to].append(v)
    used = [False] * n
    order: list[int] = []

    def dfs1(v: int) -> None:
        used[v] = True
        for to in g[v]:
            if not used[to]:
                dfs1(to)
        order.append(v)

    for i in range(n):
        if not used[i]:
            dfs1(i)

    used = [False] * n
    ids = [-1] * n
    comp = 0

    def dfs2(v: int) -> None:
        used[v] = True
        ids[v] = comp
        for to in gr[v]:
            if not used[to]:
                dfs2(to)

    for v in reversed(order):
        if not used[v]:
            dfs2(v)
            comp += 1
    return ids, comp


def tarjan(n: int, g: list[list[int]]) -> tuple[list[int], int]:
    ids = [-1] * n
    disc = [-1] * n
    low = [0] * n
    on = [False] * n
    st: list[int] = []
    timer = 0
    comp = 0

    def dfs(v: int) -> None:
        nonlocal timer, comp
        disc[v] = low[v] = timer
        timer += 1
        st.append(v)
        on[v] = True
        for to in g[v]:
            if disc[to] == -1:
                dfs(to)
                low[v] = min(low[v], low[to])
            elif on[to]:
                low[v] = min(low[v], disc[to])
        if low[v] == disc[v]:
            while True:
                u = st.pop()
                on[u] = False
                ids[u] = comp
                if u == v:
                    break
            comp += 1

    for i in range(n):
        if disc[i] == -1:
            dfs(i)
    return ids, comp

