class TwoSAT:
    def __init__(self, n: int):
        self.n = n
        self.g = [[] for _ in range(2 * n)]
        self.gr = [[] for _ in range(2 * n)]

    @staticmethod
    def NOT(x: int) -> int:
        return x ^ 1

    def add_imp(self, a: int, b: int) -> None:
        self.g[a].append(b)
        self.gr[b].append(a)

    def add_or(self, a: int, b: int) -> None:
        self.add_imp(self.NOT(a), b)
        self.add_imp(self.NOT(b), a)

    def lit(self, i: int, is_true: bool) -> int:
        return 2 * i + (0 if is_true else 1)

    def solve(self) -> list[bool] | None:
        N = 2 * self.n
        used = [False] * N
        order: list[int] = []

        def dfs1(v: int) -> None:
            used[v] = True
            for to in self.g[v]:
                if not used[to]:
                    dfs1(to)
            order.append(v)

        for i in range(N):
            if not used[i]:
                dfs1(i)

        ids = [-1] * N
        comp = 0

        def dfs2(v: int, c: int) -> None:
            ids[v] = c
            for to in self.gr[v]:
                if ids[to] == -1:
                    dfs2(to, c)

        for v in reversed(order):
            if ids[v] == -1:
                dfs2(v, comp)
                comp += 1

        assign = [False] * self.n
        for i in range(self.n):
            if ids[2 * i] == ids[2 * i + 1]:
                return None
            assign[i] = ids[2 * i] > ids[2 * i + 1]
        return assign

