def longest_on_dag(n: int, g: list[list[int]], w: list[int]) -> list[int]:
    indeg = [0] * n
    for v in range(n):
        for to in g[v]:
            indeg[to] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    order = []
    indeg2 = indeg[:]
    while q:
        v = q.popleft()
        order.append(v)
        for to in g[v]:
            indeg2[to] -= 1
            if indeg2[to] == 0:
                q.append(to)
    dp = [NEG] * n
    for v in order:
        if dp[v] == NEG:
            dp[v] = w[v]
        for to in g[v]:
            cand = dp[v] + w[to]
            if cand > dp[to]:
                dp[to] = cand
    return dp


def count_paths(n: int, g: list[list[int]], MOD: int) -> list[int]:
    indeg = [0] * n
    for v in range(n):
        for to in g[v]:
            indeg[to] += 1
    dp = [0] * n
    q = deque()
    for i in range(n):
        if indeg[i] == 0:
            q.append(i)
            dp[i] = 1
    indeg2 = indeg[:]
    while q:
        v = q.popleft()
        for to in g[v]:
            dp[to] = (dp[to] + dp[v]) % MOD
            indeg2[to] -= 1
            if indeg2[to] == 0:
                q.append(to)
    return dp

