class DSURollback:
    def __init__(self, n: int):
        self.p = list(range(n))
        self.r = [0] * n
        self.comps = n
        self.st: list[tuple] = []

    def find(self, x: int) -> int:
        while x != self.p[x]:
            x = self.p[x]
        return x

    def snapshot(self) -> int:
        return len(self.st)

    def unite(self, a: int, b: int) -> bool:
        a, b = self.find(a), self.find(b)
        if a == b:
            self.st.append((a, a, b, self.r[b], self.comps, False))
            return False
        if self.r[a] < self.r[b]:
            a, b = b, a
        self.st.append((b, self.p[b], a, self.r[a], self.comps, True))
        self.p[b] = a
        if self.r[a] == self.r[b]:
            self.r[a] += 1
        self.comps -= 1
        return True

    def rollback(self, snap: int) -> None:
        while len(self.st) > snap:
            b, pb, a, ra, comps_before, merged = self.st.pop()
            if not merged:
                continue
            self.p[b] = pb
            self.r[a] = ra
            self.comps = comps_before

