struct Edge { int u, v; };
struct Query { int u, v, time, idx; };

struct Solver {
    int n, T;
    vector<vector<Edge>> seg; // segtree of edges
    vector<vector<Query>> qat; // queries at leaf time
    vector<int> ans;

    Solver(int n, int T) : n(n), T(T), seg(4 * T), qat(T) {}

    void add_edge(int node, int tl, int tr, int l, int r, Edge e) {
        if (r <= tl || tr <= l) return;
        if (l <= tl && tr <= r) { seg[node].push_back(e); return; }
        int tm = (tl + tr) / 2;
        add_edge(node * 2, tl, tm, l, r, e);
        add_edge(node * 2 + 1, tm, tr, l, r, e);
    }
    void add_edge_interval(int L, int R, Edge e) { // alive on [L,R)
        if (L >= R) return;
        add_edge(1, 0, T, L, R, e);
    }
    void add_query(Query q) { qat[q.time].push_back(q); }

    void dfs(int node, int tl, int tr, DSU& dsu) {
        int snap = dsu.snapshot();
        for (auto e : seg[node]) dsu.unite(e.u, e.v);
        if (tl + 1 == tr) {
            for (auto& q : qat[tl]) ans[q.idx] = dsu.same(q.u, q.v);
        } else {
            int tm = (tl + tr) / 2;
            dfs(node * 2, tl, tm, dsu);
            dfs(node * 2 + 1, tm, tr, dsu);
        }
        dsu.rollback(snap);
    }

    vector<int> solve(int qcnt) {
        ans.assign(qcnt, 0);
        DSU dsu(n);
        if (T > 0) dfs(1, 0, T, dsu);
        return ans;
    }
};

/*
Typical offline compression:
- Map each unique edge (u,v) with u<v to last activation time.
- On ADD: store open time.
- On DEL: close interval [open, now).
- On QUERY: record (u,v,now).
- At end, close still-open edges at T.
*/
} // namespace offline_connectivity

// C++17, namespace-safe, contest-ready
namespace dijkstra {
using ll = long long;
const ll INF = 4e18;

vector<ll> shortest(int n, int src,
                    const vector<vector<pair<int, ll>>>& g) {
    vector<ll> dist(n, INF);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue; // lazy deletion
        for (auto [v, w] : g[u]) {
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

// Optional: recover parents
vector<ll> shortest_parent(int n, int src,
                           const vector<vector<pair<int, ll>>>& g,
                           vector<int>& par) {
    vector<ll> dist(n, INF);
    par.assign(n, -1);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (dist[v] > d + w) {
                dist[v] = d + w;
                par[v] = u;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}
} // namespace dijkstra

namespace zero_one_bfs {
using ll = long long;
const ll INF = 4e18;

vector<ll> shortest(int n, int src,
                    const vector<vector<pair<int, int>>>& g) {
    // edge weight must be 0 or 1
    vector<ll> dist(n, INF);
    deque<int> dq;
    dist[src] = 0;
    dq.push_back(src);
    while (!dq.empty()) {
        int u = dq.front();
        dq.pop_front();
        for (auto [v, w] : g[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                if (w == 0) dq.push_front(v);
                else dq.push_back(v);
            }
        }
    }
    return dist;
}
} // namespace zero_one_bfs

namespace bellman_ford {
using ll = long long;
const ll INF = 4e18;

struct Edge { int u, v; ll w; };

// returns false if negative cycle reachable from src
bool shortest(int n, int src, const vector<Edge>& edges,
              vector<ll>& dist) {
    dist.assign(n, INF);
    dist[src] = 0;
    for (int it = 0; it < n - 1; ++it) {
        bool any = false;
        for (auto [u, v, w] : edges) {
            if (dist[u] == INF) continue;
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                any = true;
            }
        }
        if (!any) break;
    }
    for (auto [u, v, w] : edges) {
        if (dist[u] == INF) continue;
        if (dist[v] > dist[u] + w) return false; // neg cycle reachable
    }
    return true;
}

// Mark nodes that can be improved via neg cycle (optional)
void mark_neg_reachable(int n, const vector<Edge>& edges,
                        vector<ll>& dist, vector<char>& bad) {
    bad.assign(n, 0);
    for (int it = 0; it < n; ++it) {
        for (auto [u, v, w] : edges) {
            if (dist[u] == INF) continue;
            if (dist[v] > dist[u] + w) {
                dist[v] = max(-INF / 4, dist[u] + w); // avoid wild overflow
                bad[v] = 1;
            }
            if (bad[u]) bad[v] = 1;
        }
    }
}
} // namespace bellman_ford

// Educational / legacy only — prefer Dijkstra or Bellman-Ford in contests.
namespace spfa {
using ll = long long;
const ll INF = 4e18;

// returns false if neg cycle detected by pop-count heuristic
bool shortest(int n, int src,
              const vector<vector<pair<int, ll>>>& g,
              vector<ll>& dist) {
    dist.assign(n, INF);
    vector<char> inq(n, 0);
    vector<int> cnt(n, 0);
    queue<int> q;
    dist[src] = 0;
    q.push(src);
    inq[src] = 1;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inq[u] = 0;
        for (auto [v, w] : g[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                if (!inq[v]) {
                    q.push(v);
                    inq[v] = 1;
                    if (++cnt[v] > n) return false; // neg cycle heuristic
                }
            }
        }
    }
    return true;
}
} // namespace spfa

namespace floyd {
using ll = long long;
const ll INF = 4e18;

void all_pairs(int n, vector<vector<ll>>& d) {
    // d[i][j] = w or INF; d[i][i] = 0
    for (int k = 0; k < n; ++k)
        for (int i = 0; i < n; ++i)
            if (d[i][k] < INF)
                for (int j = 0; j < n; ++j)
                    if (d[k][j] < INF)
                        d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
}

bool has_neg_cycle(int n, const vector<vector<ll>>& d) {
    for (int i = 0; i < n; ++i)
        if (d[i][i] < 0) return true;
    return false;
}
