namespace dag_sp {
using ll = long long;
const ll INF = 4e18;

// g must be a DAG; returns dist from src (INF = unreachable)
vector<ll> shortest(int n, int src,
                    const vector<vector<pair<int, ll>>>& g) {
    vector<int> indeg(n, 0);
    for (int u = 0; u < n; ++u)
        for (auto [v, w] : g[u]) indeg[v]++;
    queue<int> q;
    for (int i = 0; i < n; ++i)
        if (!indeg[i]) q.push(i);
    vector<int> order;
    order.reserve(n);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        order.push_back(u);
        for (auto [v, w] : g[u])
            if (--indeg[v] == 0) q.push(v);
    }
    vector<ll> dist(n, INF);
    dist[src] = 0;
    for (int u : order) {
        if (dist[u] == INF) continue;
        for (auto [v, w] : g[u])
            dist[v] = min(dist[v], dist[u] + w);
    }
    return dist;
}
} // namespace dag_sp

namespace multisource {
using ll = long long;
const ll INF = 4e18;

vector<ll> dijkstra(int n, const vector<int>& sources,
                    const vector<vector<pair<int, ll>>>& g) {
    vector<ll> dist(n, INF);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    for (int s : sources) {
        if (dist[s] > 0) {
            dist[s] = 0;
            pq.push({0, s});
        }
    }
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u]) {
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    return dist;
}

vector<int> bfs(int n, const vector<int>& sources,
                const vector<vector<int>>& g) {
    vector<int> dist(n, -1);
    queue<int> q;
    for (int s : sources) {
        if (dist[s] == -1) {
            dist[s] = 0;
            q.push(s);
        }
    }
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : g[u])
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
    }
    return dist;
}
} // namespace multisource

namespace johnson {
using ll = long long;
const ll INF = 4e18;

struct Edge { int u, v; ll w; };

// dist[u][v] = shortest; returns false on neg cycle
bool all_pairs(int n, vector<Edge> edges, vector<vector<ll>>& dist) {
    // potentials via super-source n
    vector<Edge> e2 = edges;
    for (int v = 0; v < n; ++v) e2.push_back({n, v, 0});
    vector<ll> h(n + 1, INF);
    h[n] = 0;
    for (int it = 0; it < n; ++it) {
        bool any = false;
        for (auto [u, v, w] : e2) {
            if (h[u] == INF) continue;
            if (h[v] > h[u] + w) {
                h[v] = h[u] + w;
                any = true;
            }
        }
        if (!any) break;
    }
    for (auto [u, v, w] : e2) {
        if (h[u] == INF) continue;
        if (h[v] > h[u] + w) return false;
    }

    vector<vector<pair<int, ll>>> g(n);
    for (auto [u, v, w] : edges) {
        ll nw = w + h[u] - h[v];
        g[u].push_back({v, nw});
    }

    dist.assign(n, vector<ll>(n, INF));
    for (int s = 0; s < n; ++s) {
        vector<ll> d(n, INF);
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
        d[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            auto [dd, u] = pq.top();
            pq.pop();
            if (dd != d[u]) continue;
            for (auto [v, w] : g[u]) {
                if (d[v] > dd + w) {
                    d[v] = dd + w;
                    pq.push({d[v], v});
                }
            }
        }
        for (int v = 0; v < n; ++v)
            if (d[v] < INF) dist[s][v] = d[v] - h[s] + h[v];
    }
    return true;
}
} // namespace johnson

namespace mst {
using ll = long long;

struct DSU {
    vector<int> p, r;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        r.assign(n, 0);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) ++r[a];
        return true;
    }
};

struct Edge {
    int u, v;
    ll w;
    bool operator<(const Edge& o) const { return w < o.w; }
};

// returns {total_weight, edges_in_mst}; total = -1 if not connected
pair<ll, vector<Edge>> kruskal(int n, vector<Edge> edges) {
    sort(edges.begin(), edges.end());
    DSU dsu(n);
    ll total = 0;
    vector<Edge> used;
    used.reserve(n - 1);
    for (auto e : edges) {
        if (dsu.unite(e.u, e.v)) {
            total += e.w;
            used.push_back(e);
            if ((int)used.size() == n - 1) break;
        }
    }
    if ((int)used.size() != n - 1) return {-1, {}};
    return {total, used};
}

// Prim from src; assumes connected undirected g
pair<ll, vector<Edge>> prim(int n, int src,
                            const vector<vector<pair<int, ll>>>& g) {
    vector<ll> dist(n, (ll)4e18);
    vector<int> par(n, -1);
    vector<char> in(n, 0);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});
    ll total = 0;
    int taken = 0;
    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (in[u]) continue;
        in[u] = 1;
        total += d;
        ++taken;
        for (auto [v, w] : g[u]) {
            if (!in[v] && w < dist[v]) {
                dist[v] = w;
                par[v] = u;
                pq.push({w, v});
            }
        }
    }
    if (taken != n) return {-1, {}};
    vector<Edge> used;
    for (int v = 0; v < n; ++v)
        if (par[v] != -1) used.push_back({par[v], v, dist[v]});
    return {total, used};
}
} // namespace mst

namespace kruskal_rebuild {
using ll = long long;

struct DSU {
    vector<int> p;
    DSU(int n) : p(n) { iota(p.begin(), p.end(), 0); }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
};

struct Edge {
    int u, v;
    ll w;
    bool operator<(const Edge& o) const { return w < o.w; }
};

struct Tree {
    int n_leaves = 0, N = 0, LOG = 0;
    vector<vector<int>> g;
    vector<ll> val; // internals: merge weight; leaves typically 0
    vector<int> root;
    vector<int> dep;
    vector<vector<int>> up;

    int lca(int a, int b) const {
        if (dep[a] < dep[b]) swap(a, b);
        int d = dep[a] - dep[b];
        for (int j = 0; j < LOG; ++j)
            if (d & (1 << j)) a = up[j][a];
        if (a == b) return a;
        for (int j = LOG - 1; j >= 0; --j)
            if (up[j][a] != up[j][b]) {
                a = up[j][a];
                b = up[j][b];
            }
        return up[0][a];
    }

    int component_root(int x) const {
        while (up[0][x] != x) x = up[0][x];
        return x;
    }

    // minimax edge on path between leaves a,b; -1 if disconnected
    ll path_max(int a, int b) const {
        if (component_root(a) != component_root(b)) return -1;
        int p = lca(a, b);
        return (p < n_leaves) ? 0 : val[p]; // same leaf / degenerate
    }
};

// Leaves 0..n-1; each Kruskal merge creates a new parent with val = edge weight.
Tree build(int n, vector<Edge> edges) {
    sort(edges.begin(), edges.end());
    Tree t;
    t.n_leaves = n;
    int Nmax = 2 * n;
    t.g.assign(Nmax, {});
    t.val.assign(Nmax, 0);
    DSU dsu(n);
    vector<int> root_of(n);
    iota(root_of.begin(), root_of.end(), 0);
    t.N = n;
    for (auto e : edges) {
        int a = dsu.find(e.u), b = dsu.find(e.v);
        if (a == b) continue;
        int p = t.N++;
        t.val[p] = e.w;
        t.g[p] = {root_of[a], root_of[b]}; // rooted: children only
        dsu.p[b] = a;
        root_of[a] = p;
    }
    vector<char> has_parent(t.N, 0);
    for (int u = n; u < t.N; ++u)
        for (int v : t.g[u]) has_parent[v] = 1;
    t.root.clear();
    for (int i = 0; i < t.N; ++i)
        if (!has_parent[i]) t.root.push_back(i);

    t.LOG = 1;
    while ((1 << t.LOG) <= t.N) ++t.LOG;
    t.dep.assign(t.N, 0);
    t.up.assign(t.LOG, vector<int>(t.N));
    for (int r : t.root) {
        t.up[0][r] = r;
        vector<int> st = {r};
        while (!st.empty()) {
            int u = st.back();
            st.pop_back();
            for (int v : t.g[u]) {
                t.up[0][v] = u;
                t.dep[v] = t.dep[u] + 1;
                st.push_back(v);
            }
        }
    }
    for (int j = 1; j < t.LOG; ++j)
        for (int i = 0; i < t.N; ++i)
            t.up[j][i] = t.up[j - 1][t.up[j - 1][i]];
    return t;
}
} // namespace kruskal_rebuild

namespace boruvka {
using ll = long long;

struct DSU {
    vector<int> p, r;
    DSU(int n) : p(n), r(n, 0) { iota(p.begin(), p.end(), 0); }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return false;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) ++r[a];
        return true;
    }
};

struct Edge { int u, v; ll w; };

// returns MST weight or -1 if disconnected
ll mst(int n, const vector<Edge>& edges) {
    DSU dsu(n);
    ll total = 0;
    int comps = n;
    vector<int> best(n);
    vector<ll> best_w(n);
    while (comps > 1) {
        fill(best.begin(), best.end(), -1);
        fill(best_w.begin(), best_w.end(), (ll)4e18);
        for (int i = 0; i < (int)edges.size(); ++i) {
            int a = dsu.find(edges[i].u), b = dsu.find(edges[i].v);
            if (a == b) continue;
            if (edges[i].w < best_w[a]) {
                best_w[a] = edges[i].w;
                best[a] = i;
            }
            if (edges[i].w < best_w[b]) {
                best_w[b] = edges[i].w;
                best[b] = i;
            }
        }
        bool progressed = false;
        for (int c = 0; c < n; ++c) {
            if (dsu.find(c) != c || best[c] == -1) continue;
            auto e = edges[best[c]];
            if (dsu.unite(e.u, e.v)) {
                total += e.w;
                --comps;
                progressed = true;
            }
        }
        if (!progressed) return -1;
    }
    return total;
}
} // namespace boruvka

namespace euler {
// Undirected Hierholzer. edges as adj[u] = list of {to, edge_id}
// Each undirected edge once in `used`
vector<int> undirected_trail(int n, int m,
                             vector<vector<pair<int, int>>>& adj,
                             int start = -1) {
    vector<char> used(m, 0);
    vector<int> deg(n, 0);
    for (int u = 0; u < n; ++u) deg[u] = (int)adj[u].size();
    int odd = 0, any = -1;
    for (int u = 0; u < n; ++u) {
        if (deg[u]) any = u;
        if (deg[u] & 1) {
            ++odd;
            start = u;
        }
    }
    if (any == -1) return {}; // no edges
    if (odd != 0 && odd != 2) return {}; // impossible
    if (start < 0) start = any;

    vector<int> st, path;
    st.push_back(start);
    vector<int> it(n, 0);
    while (!st.empty()) {
        int u = st.back();
        while (it[u] < (int)adj[u].size() && used[adj[u][it[u]].second]) ++it[u];
        if (it[u] == (int)adj[u].size()) {
            path.push_back(u);
            st.pop_back();
        } else {
            auto [v, id] = adj[u][it[u]];
            ++it[u];
            if (used[id]) continue;
            used[id] = 1;
            st.push_back(v);
        }
    }
    if ((int)path.size() != m + 1) return {}; // not connected on edges
    reverse(path.begin(), path.end());
    return path; // vertex sequence
}

// Directed: adj[u] = list of {to, edge_id}; m edges
vector<int> directed_trail(int n, int m,
                           vector<vector<pair<int, int>>>& adj,
                           const vector<int>& indeg,
                           const vector<int>& outdeg) {
    int start = -1, end = -1;
    for (int i = 0; i < n; ++i) {
        if (outdeg[i] == indeg[i] + 1) {
            if (start != -1) return {};
            start = i;
        } else if (indeg[i] == outdeg[i] + 1) {
            if (end != -1) return {};
            end = i;
        } else if (indeg[i] != outdeg[i]) return {};
    }
    if (start == -1) {
        for (int i = 0; i < n; ++i)
            if (outdeg[i]) {
                start = i;
                break;
            }
    }
    if (start == -1) return {};

    vector<char> used(m, 0);
    vector<int> it(n, 0), st, path;
    st.push_back(start);
    while (!st.empty()) {
        int u = st.back();
        while (it[u] < (int)adj[u].size() && used[adj[u][it[u]].second]) ++it[u];
        if (it[u] == (int)adj[u].size()) {
            path.push_back(u);
            st.pop_back();
        } else {
            auto [v, id] = adj[u][it[u]++];
            if (used[id]) continue;
            used[id] = 1;
            st.push_back(v);
        }
    }
    if ((int)path.size() != m + 1) return {};
    reverse(path.begin(), path.end());
    return path;
}
} // namespace euler

namespace functional {
// next[u] in [0..n)
struct Info {
    vector<int> next;
    vector<int> cyc_id;      // -1 if not on cycle; else cycle index
    vector<int> cyc_pos;     // position on cycle
    vector<int> cyc_len;
    vector<int> dist_to_cyc; // 0 if on cycle
    vector<int> entry;       // first cycle vertex reached
    vector<vector<int>> cycles;
};

Info analyze(const vector<int>& next) {
    int n = (int)next.size();
    Info info;
    info.next = next;
    info.cyc_id.assign(n, -1);
    info.cyc_pos.assign(n, -1);
    info.dist_to_cyc.assign(n, -1);
    info.entry.assign(n, -1);
    vector<int> state(n, 0); // 0=unseen,1=visiting,2=done
    vector<int> stack;
    stack.reserve(n);

    for (int s = 0; s < n; ++s) {
        if (state[s]) continue;
        int u = s;
        while (state[u] == 0) {
            state[u] = 1;
            stack.push_back(u);
            u = next[u];
        }
        if (state[u] == 1) {
            // found cycle ending at u
            vector<int> cyc;
            while (true) {
                int x = stack.back();
                stack.pop_back();
                state[x] = 2;
                cyc.push_back(x);
                if (x == u) break;
            }
            reverse(cyc.begin(), cyc.end());
            int cid = (int)info.cycles.size();
            info.cycles.push_back(cyc);
            info.cyc_len.push_back((int)cyc.size());
            for (int i = 0; i < (int)cyc.size(); ++i) {
                int x = cyc[i];
                info.cyc_id[x] = cid;
                info.cyc_pos[x] = i;
                info.dist_to_cyc[x] = 0;
                info.entry[x] = x;
            }
        }
        while (!stack.empty()) {
            int x = stack.back();
            stack.pop_back();
            state[x] = 2;
        }
    }

    // dists for tree nodes: walk forward (memo)
    for (int v = 0; v < n; ++v) {
        if (info.dist_to_cyc[v] != -1) continue;
        vector<int> path;
        int u = v;
        while (info.dist_to_cyc[u] == -1) {
            path.push_back(u);
            u = next[u];
        }
        int d = info.dist_to_cyc[u];
        int ent = info.entry[u];
        for (int i = (int)path.size() - 1; i >= 0; --i) {
            ++d;
            info.dist_to_cyc[path[i]] = d;
            info.entry[path[i]] = ent;
            info.cyc_id[path[i]] = info.cyc_id[ent];
        }
    }
    return info;
}

// binary lifting for f^k
struct Lift {
    int LOG;
    vector<vector<int>> up;
    Lift(const vector<int>& next, int max_pow = 60) {
        int n = (int)next.size();
        LOG = max_pow;
        up.assign(LOG, vector<int>(n));
        up[0] = next;
        for (int j = 1; j < LOG; ++j)
            for (int i = 0; i < n; ++i)
                up[j][i] = up[j - 1][up[j - 1][i]];
    }
    int jump(int v, long long k) const {
        for (int j = 0; j < LOG && k; ++j)
            if (k & (1LL << j)) {
                v = up[j][v];
                k ^= (1LL << j);
            }
        return v;
    }
};
} // namespace functional

