struct MaxFlow {
  int n;
  vector<vector<Edge>> g;
  explicit MaxFlow(int n) : n(n), g(n) {}
  void add_edge(int u, int v, long long c) {
    Edge a{v, (int)g[v].size(), c};
    Edge b{u, (int)g[u].size(), 0};
    g[u].push_back(a); g[v].push_back(b);
  }
