    dp = [INF] * (n + 1)
    dp[0] = 0
    dq = deque()
    def val(j): return dp[j] + add(j)
    for i in range(1, n + 1):
        j = i - 1
        while dq and val(dq[-1]) >= val(j):
            dq.pop()
        dq.append(j)
        while dq and dq[0] < i - W:
            dq.popleft()
        if dq:
            dp[i] = val(dq[0]) + fee[i]
    return dp

