vector<ll> or_convolution(vector<ll> f, vector<ll> g) {
    int N = (int)f.size();
    zeta_subsets(f);
    zeta_subsets(g);
    vector<ll> h(N);
    for (int i = 0; i < N; ++i) h[i] = f[i] * g[i];
