namespace sam {
struct SAM {
    static constexpr int SIG = 26;
    struct State {
        int next[SIG];
        int link = -1, len = 0;
        long long occ = 0; // endpos size after propagate
        State() { fill(next, next + SIG, -1); }
    };
    vector<State> st;
    int last = 0;

    SAM(int maxlen = 0) {
        st.reserve(2 * maxlen + 5);
        st.push_back(State());
    }

    void extend(int c) {
        int cur = (int)st.size();
        st.push_back(State());
        st[cur].len = st[last].len + 1;
        st[cur].occ = 1; // real end
        int p = last;
        while (p != -1 && st[p].next[c] == -1) {
            st[p].next[c] = cur;
            p = st[p].link;
        }
        if (p == -1) {
            st[cur].link = 0;
        } else {
            int q = st[p].next[c];
            if (st[p].len + 1 == st[q].len) {
                st[cur].link = q;
            } else {
                int cl = (int)st.size();
                st.push_back(st[q]); // copy transitions, link
                st[cl].len = st[p].len + 1;
                st[cl].occ = 0; // clone
                while (p != -1 && st[p].next[c] == q) {
                    st[p].next[c] = cl;
                    p = st[p].link;
                }
                st[q].link = st[cur].link = cl;
            }
        }
        last = cur;
    }

