namespace eertree {
struct Eertree {
    static constexpr int SIG = 26;
    struct Node {
        int next[SIG];
        int link = 0, len = 0;
        long long cnt = 0;
        Node() { fill(next, next + SIG, -1); }
    };
    vector<Node> st;
    string s;
    int last = 0;

    Eertree() {
        st.push_back(Node()); // 0: len 0 even root, link 1
        st.push_back(Node()); // 1: len -1 odd root, link 1
        st[0].link = 1;
        st[1].link = 1;
        st[0].len = 0;
        st[1].len = -1;
        last = 0;
    }

    void add(char ch) {
        int c = ch - 'a';
        int pos = (int)s.size();
        s.push_back(ch);
        int p = last;
        while (true) {
            int L = st[p].len;
            if (pos - L - 1 >= 0 && s[pos - L - 1] == ch) break;
            p = st[p].link;
        }
        if (st[p].next[c] != -1) {
            last = st[p].next[c];
            st[last].cnt++;
            return;
        }
        int cur = (int)st.size();
        st.push_back(Node());
        st[cur].len = st[p].len + 2;
        st[p].next[c] = cur;
        if (st[cur].len == 1) {
            st[cur].link = 0;
        } else {
            int q = st[p].link;
            while (true) {
                int L = st[q].len;
                if (pos - L - 1 >= 0 && s[pos - L - 1] == ch) break;
                q = st[q].link;
            }
            st[cur].link = st[q].next[c];
        }
        last = cur;
        st[cur].cnt = 1;
    }

    long long distinct_palindromes() const {
        return (long long)st.size() - 2;
    }
};
} // namespace eertree

