namespace binpow {
using i64 = long long;
i64 mod_pow(i64 a, i64 e, i64 mod) {
    a %= mod;
    if (a < 0) a += mod;
    i64 r = 1 % mod;
    while (e > 0) {
        if (e & 1) r = (__int128)r * a % mod;
        a = (__int128)a * a % mod;
        e >>= 1;
    }
    return r;
}
// unmodular: overflow risk — use only when result fits type
i64 pow_i64(i64 a, i64 e) {
    i64 r = 1;
    while (e > 0) {
        if (e & 1) r *= a;
        a *= a;
        e >>= 1;
    }
    return r;
}
} // namespace binpow

