def crt2(a: int, m: int, b: int, n: int) -> tuple[int, int] | None:
    g, x, _ = egcd(m, n)
    if (b - a) % g:
        return None
    mod = n // g
    t = ((b - a) // g * x) % mod
    lcm = m // g * n
    return (a + m * t) % lcm, lcm

def crt_all(aa: list[int], mm: list[int]) -> tuple[int, int] | None:
    A, M = 0, 1
    for a, m in zip(aa, mm):
        merged = crt2(A, M, a % m, m)
        if merged is None:
            return None
        A, M = merged
    return A, M

