i64 count_free(i64 n, const std::vector<i64>& a) {
    int m = (int)a.size();
    i64 ans = 0;
    for (int mask = 1; mask < (1 << m); ++mask) {
        i64 l = 1;
        bool ok = true;
        int bits = 0;
        for (int i = 0; i < m; ++i) if (mask & (1 << i)) {
            ++bits;
            if (l > n / a[i]) { ok = false; break; } // lcm overflow guard (approx)
            i64 g = std::gcd(l, a[i]);
            l = l / g * a[i];
        }
        if (!ok || l == 0) continue;
        i64 add = n / l;
        ans += (bits % 2 ? add : -add);
    }
    return n - ans; // none of the a_i divide
}
