i64 surjections(int n, int k, int mod, const modinv::FactInv& fi) {
    i64 ans = 0;
    for (int i = 0; i <= k; ++i) {
        i64 ways = binpow::mod_pow(k - i, n, mod);
        i64 term = (i64)fi.C(k, i) * ways % mod;
        if (i & 1) ans = (ans - term) % mod;
        else ans = (ans + term) % mod;
    }
    if (ans < 0) ans += mod;
    return ans;
}
