import cmath

def fft(a: list[complex], invert: bool = False) -> None:
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        ang = 2 * cmath.pi / length * (-1 if invert else 1)
        wlen = cmath.exp(complex(0, ang))
        for i in range(0, n, length):
            w = 1 + 0j
            half = length // 2
            for j in range(half):
                u, v = a[i + j], a[i + j + half] * w
                a[i + j], a[i + j + half] = u + v, u - v
                w *= wlen
        length <<= 1
    if invert:
        for i in range(n):
            a[i] /= n

def multiply(a: list[int], b: list[int]) -> list[int]:
    n = 1
    while n < len(a) + len(b):
        n <<= 1
    fa = [complex(x) for x in a] + [0j] * (n - len(a))
    fb = [complex(x) for x in b] + [0j] * (n - len(b))
    fft(fa); fft(fb)
    for i in range(n):
        fa[i] *= fb[i]
    fft(fa, invert=True)
    return [int(round(fa[i].real)) for i in range(n)]

