    mid = len(a) // 2
    left = sorted(subset_sums(a[:mid]))
    right = sorted(subset_sums(a[mid:]))
    ans = 0
    for x in left:
        need = target - x
        ans += bisect_right(right, need) - bisect_left(right, need)
    return ans

